import { PaymentRepository } from '../repositories/payment-repository.js';

const payments = new PaymentRepository();

// Keeps the callback signatures for existing callers (routes.js).
export function findPaymentsForOrder(orderId, callback) {
  payments.findByOrder(orderId).then((rows) => callback(null, rows), callback);
}

export function uncapturedTotalCents(callback) {
  payments.findUncaptured().then(
    (rows) => callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0)),
    callback,
  );
}

