cat >> tests/repositories.test.js <<'EOF'

test('PaymentRepository.findByOrders returns payments for any of the orders', async () => {
  const repo = new PaymentRepository();
  const payments = await repo.findByOrders([10, 11, 12]);
  assert.deepEqual(payments.map((p) => p.id), [100, 101]);
  assert.deepEqual(await repo.findByOrders([]), []);
});
EOF
sed -i "s/^import { findPaymentsForOrder, uncapturedTotalCents } from/import { findPaymentsForOrder, uncapturedTotalCents, listPaymentsForUser } from/" tests/payment-service.test.js
sed -i "4a import { OrderRepository } from '../src/repositories/order-repository.js';" tests/payment-service.test.js
cat >> tests/payment-service.test.js <<'EOF'

test('listPaymentsForUser returns payments on that user orders', (t, done) => {
  listPaymentsForUser(1, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(rows.map((p) => p.id), [100]);
    done();
  });
});

test('listPaymentsForUser returns an empty list for an unknown user', (t, done) => {
  listPaymentsForUser(999, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(rows, []);
    done();
  });
});

test('listPaymentsForUser passes repository errors to the callback', (t, done) => {
  const boom = new Error('boom');
  t.mock.method(OrderRepository.prototype, 'findByUser', () => Promise.reject(boom));
  listPaymentsForUser(1, (err, rows) => {
    assert.equal(err, boom);
    assert.equal(rows, undefined);
    done();
  });
});
EOF
cat > tests/routes.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { routes } from '../src/api/routes.js';

function findRoute(method, path) {
  return routes.find((r) => r.method === method && r.path === path);
}

test('GET /users/:id/payments returns that user payments', (t, done) => {
  const route = findRoute('GET', '/users/:id/payments');
  assert.ok(route);
  route.handler({ params: { id: '2' } }, (err, rows) => {
    assert.equal(err, null);
    assert.deepEqual(rows.map((p) => p.id), [101]);
    done();
  });
});
EOF
head -6 tests/payment-service.test.js; npm test 2>&1 | tail -28; npm run lint 2>&1 | tail -2; node scripts/check-routes.js

